/* Additional offline shop modules. Kept separate from app.js for easier maintenance. */
const featureModules = ['products','attendance','payroll','offers','reminders'];
const featureTitles = {products:'المنتجات والمخزون',attendance:'الحضور والانصراف',payroll:'الرواتب والعمولات',offers:'العروض والخصومات',reminders:'التذكيرات'};
let featureAppointmentView='day',featureAppointmentDate=today,featureReminderTimer=null,featureActiveAppointmentId='';
const featureArrays=['products','productMovements','attendance','payroll','offers','reminders','employeeDetails'];
function featureEnsureData(){
  for(const k of featureArrays) if(!Array.isArray(db[k])) db[k]=[];
  db.settings={language:'ar',theme:'light',taxRate:0,loyaltyEarnRate:10,loyaltyPointValue:0.1,...db.settings};
  if(!initial.products) initial.products=[];
  if(!initial.attendance) initial.attendance=[];
  if(!initial.payroll) initial.payroll=[];
  if(!initial.offers) initial.offers=[];
  if(!initial.reminders) initial.reminders=[];if(!initial.employeeDetails) initial.employeeDetails=[];
  initial.settings={...initial.settings,language:'ar',theme:'light',taxRate:0,loyaltyEarnRate:10,loyaltyPointValue:0.1};
}
featureEnsureData();

const featureBaseWorkbook=makeDatabaseWorkbook;
makeDatabaseWorkbook=function(){
  const wb=featureBaseWorkbook();
  const setSheet=(name,headers,rows)=>{wb.Sheets[name]=XLSX.utils.aoa_to_sheet([headers,...rows]);if(!wb.SheetNames.includes(name))wb.SheetNames.push(name)};
  setSheet('الحلاقون',['id','name','phone','commission','active','baseSalary'],db.barbers.map(b=>[b.id,b.name,b.phone,b.commission,b.active,b.baseSalary||0]));
  setSheet('المبيعات',['id','date','createdAt','client','clientPhone','barberId','chairId','payment','total','commission','customers','items','subtotal','discount','discountAmount','taxRate','tax','offerId','pointsEarned','pointsRedeemed','invoiceNo','appointmentId'],db.sales.map(s=>[s.id,s.date,s.createdAt,s.client,s.clientPhone||'',s.barberId,s.chairId,s.payment,s.total,s.commission,s.customers,JSON.stringify(s.items||[]),s.subtotal??s.total,s.discount||0,s.discountAmount||0,s.taxRate||0,s.tax||0,s.offerId||'',s.pointsEarned||0,s.pointsRedeemed||0,s.invoiceNo||'',s.appointmentId||'']));
  setSheet('الحجوزات',['id','client','phone','date','time','serviceId','barberId','status','notes','reminderAt'],db.appointments.map(a=>[a.id,a.client,a.phone,a.date,a.time,a.serviceId,a.barberId,a.status,a.notes||'',a.reminderAt||'']));
  setSheet('المنتجات',['id','name','sku','barcode','price','cost','stock','minStock','active'],db.products.map(x=>[x.id,x.name,x.sku||'',x.barcode||'',x.price||0,x.cost||0,x.stock||0,x.minStock||0,x.active!==false]));
  setSheet('حركة المنتجات',['id','productId','date','type','quantity','amount','saleId','expenseId','note'],db.productMovements.map(x=>[x.id,x.productId,x.date,x.type,x.quantity,x.amount||0,x.saleId||'',x.expenseId||'',x.note||'']));
  setSheet('الحضور',['id','barberId','date','checkIn','checkOut','source','note'],db.attendance.map(x=>[x.id,x.barberId,x.date,x.checkIn||'',x.checkOut||'',x.source||'يدوي',x.note||'']));
  setSheet('بيانات الموظفين',['employeeId','baseSalary','name'],db.employeeDetails.map(x=>[x.employeeId,x.baseSalary||0,x.name||'']));
  setSheet('الرواتب',['id','barberId','period','baseSalary','commission','advance','incentive','deduction','paid','paymentDate','note'],db.payroll.map(x=>[x.id,x.barberId,x.period,x.baseSalary||0,x.commission||0,x.advance||0,x.incentive||0,x.deduction||0,x.paid||0,x.paymentDate||'',x.note||'']));
  setSheet('العروض',['id','name','type','value','start','end','minTotal','active'],db.offers.map(x=>[x.id,x.name,x.type||'percent',x.value||0,x.start||'',x.end||'',x.minTotal||0,x.active!==false]));
  setSheet('التذكيرات',['id','appointmentId','client','phone','date','time','channel','status','note'],db.reminders.map(x=>[x.id,x.appointmentId||'',x.client||'',x.phone||'',x.date,x.time,x.channel||'local',x.status||'pending',x.note||'']));
  return wb;
};
const featureBaseWorkbookData=workbookData;
workbookData=function(wb){
  const parsed=featureBaseWorkbookData(wb),data=parsed.data;
  const rows=name=>sheetRows(wb,name);
  const map=(name,fn)=>rows(name).map(fn);
  data.barbers=map('الحلاقون',r=>({id:String(r.id),name:String(r.name||''),phone:String(r.phone||''),commission:Number(r.commission)||0,active:r.active===true||String(r.active).toLowerCase()==='true',baseSalary:Number(r.baseSalary)||0}));
  data.sales=map('المبيعات',r=>({id:String(r.id),date:String(r.date),createdAt:String(r.createdAt),client:String(r.client||''),clientPhone:String(r.clientPhone||''),barberId:String(r.barberId||''),chairId:String(r.chairId||''),payment:String(r.payment||'cash'),total:Number(r.total)||0,commission:Number(r.commission)||0,customers:Number(r.customers)||1,items:(()=>{try{return JSON.parse(r.items||'[]')}catch{return[]}})(),subtotal:Number(r.subtotal)||Number(r.total)||0,discount:Number(r.discount)||0,discountAmount:Number(r.discountAmount)||0,taxRate:Number(r.taxRate)||0,tax:Number(r.tax)||0,offerId:String(r.offerId||''),pointsEarned:Number(r.pointsEarned)||0,pointsRedeemed:Number(r.pointsRedeemed)||0,invoiceNo:String(r.invoiceNo||r.id||''),appointmentId:String(r.appointmentId||'')}));
  data.appointments=map('الحجوزات',r=>({id:String(r.id),client:String(r.client||''),phone:String(r.phone||''),date:String(r.date||''),time:String(r.time||''),serviceId:String(r.serviceId||''),barberId:String(r.barberId||''),status:String(r.status||'booked'),notes:String(r.notes||''),reminderAt:String(r.reminderAt||'')}));
  data.products=map('المنتجات',r=>({id:String(r.id),name:String(r.name||''),sku:String(r.sku||''),barcode:String(r.barcode||''),price:Number(r.price)||0,cost:Number(r.cost)||0,stock:Number(r.stock)||0,minStock:Number(r.minStock)||0,active:r.active===true||String(r.active).toLowerCase()==='true'}));
  data.productMovements=map('حركة المنتجات',r=>({id:String(r.id),productId:String(r.productId||''),date:String(r.date||''),type:String(r.type||''),quantity:Number(r.quantity)||0,amount:Number(r.amount)||0,saleId:String(r.saleId||''),expenseId:String(r.expenseId||''),note:String(r.note||'')}));
  data.attendance=map('الحضور',r=>({id:String(r.id),barberId:String(r.barberId||''),date:String(r.date||''),checkIn:String(r.checkIn||''),checkOut:String(r.checkOut||''),source:String(r.source||'يدوي'),note:String(r.note||'')}));
  data.employeeDetails=map('بيانات الموظفين',r=>({employeeId:String(r.employeeId||''),baseSalary:Number(r.baseSalary)||0,name:String(r.name||'')}));
  data.payroll=map('الرواتب',r=>({id:String(r.id),barberId:String(r.barberId||''),period:String(r.period||''),baseSalary:Number(r.baseSalary)||0,commission:Number(r.commission)||0,advance:Number(r.advance)||0,incentive:Number(r.incentive)||0,deduction:Number(r.deduction)||0,paid:Number(r.paid)||0,paymentDate:String(r.paymentDate||''),note:String(r.note||'')}));
  data.offers=map('العروض',r=>({id:String(r.id),name:String(r.name||''),type:String(r.type||'percent'),value:Number(r.value)||0,start:String(r.start||''),end:String(r.end||''),minTotal:Number(r.minTotal)||0,active:r.active===true||String(r.active).toLowerCase()==='true'}));
  data.reminders=map('التذكيرات',r=>({id:String(r.id),appointmentId:String(r.appointmentId||''),client:String(r.client||''),phone:String(r.phone||''),date:String(r.date||''),time:String(r.time||''),channel:String(r.channel||'local'),status:String(r.status||'pending'),note:String(r.note||'')}));
  return parsed;
};

function featureCanAccess(p){if(!currentUser)return false;if(p==='settings'||p==='users')return currentUser.role==='admin';const allowed=Array.isArray(currentUser.permissions)?currentUser.permissions:['cashier','appointments','customers'];return allowed.includes(p)}
function featureSetPage(p){if(!featureCanAccess(p)){toast('الصفحة دي متاحة للمدير فقط');return}page=p;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.getElementById('crumb').textContent=pageNames[p]||featureTitles[p]||p;render()}
for(const [k,v] of Object.entries(featureTitles))pageNames[k]=v;
canAccessPage=featureCanAccess;
const featureBaseRequireManager=requireManager;requireManager=function(){return isManager()||currentUser?.permissions?.includes(page)?true:featureBaseRequireManager()};
const featureBaseSetUser=setCurrentUser;setCurrentUser=function(user){if(user?.role==='admin'){user={...adminProfile,...user,permissions:adminProfile.permissions}}else if(user?.username){const saved=appUsers.find(x=>x.username.toLowerCase()===user.username.toLowerCase());if(saved)user={...saved,...user,role:saved.role,permissions:saved.permissions}}featureBaseSetUser(user)};
go=featureSetPage;
const featureBaseRender=render;
render=function(){featureEnsureData();featureApplyPrefs();if(currentUser&&!featureCanAccess(page))page=featurePermissionPages.find(x=>featureCanAccess(x))||'dashboard';applyRoleUi();if(featureModules.includes(page)||['appointments','customers','cashier','settings','users'].includes(page)){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumb').textContent=pageNames[page]||featureTitles[page];document.getElementById('navOpen').textContent=db.closes.some(c=>c.date===today)?'مغلق':'مفتوح';const el=document.getElementById('page');el.innerHTML=featurePageMap[page]();featureWire();if(excelSyncing)setExcelStatus('connected','Excel محفوظ');return}featureBaseRender();featureApplyLocale()};
const featurePageMap={products:featureProductsPage,attendance:featureAttendancePage,payroll:featurePayrollPage,offers:featureOffersPage,reminders:featureRemindersPage,appointments:featureAppointmentsPage,customers:featureCustomersPage,cashier:featureCashierPage,settings:featureSettingsPage,users:usersPage};

function featureServiceLines(sale){return (sale.items||[]).filter(i=>!i.productId)}
function featureStaff(){const accountStaff=appUsers.filter(u=>u.active).map(u=>{const id=`u:${u.username}`,detail=db.employeeDetails.find(x=>x.employeeId===id);return{id,name:u.name,username:u.username,active:true,role:'cashier',baseSalary:Number(detail?.baseSalary)||0,accountId:u.id}});return [...db.barbers.filter(b=>b.active),...accountStaff]}
function featureStaffName(id){return db.barbers.find(b=>b.id===id)?.name||appUsers.find(u=>`u:${u.username}`===id||u.id===id)?.name||db.employeeDetails.find(x=>x.employeeId===id)?.name||'—'}
barberName=function(id){return featureStaffName(id)};
commissionFor=function(sale){const serviceTotal=featureServiceLines(sale).reduce((a,i)=>a+(Number(i.price)||0),0);const invoiceSubtotal=Number(sale.subtotal)||Number(sale.total)||0;const discount=Math.min(serviceTotal,(Number(sale.discountAmount)||0)*(invoiceSubtotal?serviceTotal/invoiceSubtotal:0));const rate=Number(sale.commission??db.barbers.find(b=>b.id===sale.barberId)?.commission??db.settings.commission)||0;return Math.round(Math.max(0,serviceTotal-discount)*rate/100)};
function featureCustomerPoints(phone){const clean=String(phone||'').replace(/\D/g,'');if(!clean)return 0;return db.sales.filter(s=>String(s.clientPhone||'').replace(/\D/g,'')===clean).reduce((n,s)=>n+(Number(s.pointsEarned)||0)-(Number(s.pointsRedeemed)||0),0)}
function featurePaymentLabel(p){return p==='cash'?'نقدي':p==='card'?'بطاقة':p==='wallet'?'محفظة إلكترونية':'أخرى'}
function featureInvoiceNo(s){return s.invoiceNo||('H-'+String(s.id||'').slice(-6).toUpperCase())}
function featureSaleLine(i){return i.productId?db.products.find(p=>p.id===i.productId)?.name||'منتج محذوف':serviceName(i.serviceId)}
function featureOffersForTotal(total){return db.offers.filter(o=>o.active!==false&&(!o.start||today>=o.start)&&(!o.end||today<=o.end)&&total>=Number(o.minTotal||0))}

function featureProductsPage(){const low=db.products.filter(p=>p.active!==false&&Number(p.stock)<=Number(p.minStock||0));return `${pageHead('المنتجات والمخزون','إدارة المنتجات والأسعار والكميات المتاحة.',`<button class="btn" data-fa="export-products">تصدير CSV</button><button class="btn btn-primary" data-fa="product-add">＋ منتج جديد</button>`)}<div class="grid stats-grid">${stat('عدد المنتجات',db.products.filter(p=>p.active!==false).length,'▣','منتج نشط')}${stat('قيمة المخزون',money(db.products.reduce((n,p)=>n+p.stock*p.cost,0)),'◈','بسعر التكلفة')}${stat('أصناف منخفضة',low.length,'↓','عند حد التنبيه أو أقل')}${stat('منتجات غير نشطة',db.products.filter(p=>p.active===false).length,'◷','مخفية من الكاشير')}</div><div class="card panel"><div class="panel-header"><div><h2>قائمة المنتجات</h2><p>المبيعات تخصم الكمية تلقائيًا، والمشتريات تسجل كمصروف.</p></div><input class="input" id="productSearch" placeholder="ابحث بالاسم أو الكود" style="width:220px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>المنتج</th><th>الكود</th><th>سعر البيع</th><th>التكلفة</th><th>الرصيد</th><th>الحالة</th><th></th></tr></thead><tbody>${db.products.length?db.products.map(p=>`<tr data-product-row><td><strong>${esc(p.name)}</strong></td><td>${esc(p.sku||p.barcode||'—')}</td><td>${money(p.price)}</td><td>${money(p.cost)}</td><td>${p.stock} <small>${esc(p.unit||'قطعة')}</small></td><td>${p.active===false?'موقوف':p.stock<=p.minStock?'منخفض':'متاح'}</td><td><button class="btn btn-small" data-fa="product-edit" data-id="${p.id}">تعديل</button> <button class="btn btn-small btn-soft" data-fa="product-buy" data-id="${p.id}">شراء</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">أضف المنتجات التي يبيعها المحل</td></tr>'}</tbody></table></div></div>`}
const featureProductsBasePage=featureProductsPage;
featureProductsPage=function(){return featureProductsBasePage()+`<div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>حركة مخزون المنتجات</h2><p>مشتريات ومبيعات المنتجات المسجلة على الفواتير</p></div><button class="btn" data-fa="export-product-movements">تصدير الحركة CSV</button></div>${db.productMovements.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ</th><th>المنتج</th><th>الحركة</th><th>الكمية</th><th>القيمة</th><th>ملاحظة</th></tr></thead><tbody>${db.productMovements.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td>${dateFmt(m.date)}</td><td>${esc(db.products.find(p=>p.id===m.productId)?.name||'منتج محذوف')}</td><td>${esc(m.type)}</td><td>${m.quantity}</td><td>${money(m.amount)}</td><td>${esc(m.note||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">تظهر حركة المخزون عند تسجيل شراء أو بيع منتج</div>'}</div>`};
function featureProductModal(id){const p=db.products.find(x=>x.id===id)||{name:'',sku:'',barcode:'',price:0,cost:0,stock:0,minStock:0,active:true};showModal(id?'تعديل منتج':'إضافة منتج',`<form id="featureProductForm"><div class="form-grid"><div class="field full"><label>اسم المنتج *</label><input class="input" name="name" required value="${esc(p.name)}"></div><div class="field"><label>كود الصنف</label><input class="input" name="sku" value="${esc(p.sku||'')}"></div><div class="field"><label>باركود</label><input class="input" name="barcode" value="${esc(p.barcode||'')}"></div><div class="field"><label>سعر البيع *</label><input class="input" name="price" type="number" min="0" step="0.01" required value="${p.price}"></div><div class="field"><label>تكلفة الشراء</label><input class="input" name="cost" type="number" min="0" step="0.01" value="${p.cost}"></div><div class="field"><label>الرصيد الحالي</label><input class="input" name="stock" type="number" min="0" step="0.001" value="${p.stock}"></div><div class="field"><label>حد التنبيه</label><input class="input" name="minStock" type="number" min="0" step="0.001" value="${p.minStock}"></div><div class="field full"><label><input type="checkbox" name="active" ${p.active!==false?'checked':''}> المنتج متاح للبيع</label></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="featureProductSave">حفظ</button>`);document.getElementById('featureProductSave').onclick=()=>{const f=new FormData(document.getElementById('featureProductForm'));if(!String(f.get('name')||'').trim())return toast('أدخل اسم المنتج');const data={id:id||uid(),name:String(f.get('name')).trim(),sku:String(f.get('sku')||'').trim(),barcode:String(f.get('barcode')||'').trim(),price:Number(f.get('price'))||0,cost:Number(f.get('cost'))||0,stock:Number(f.get('stock'))||0,minStock:Number(f.get('minStock'))||0,active:f.has('active')};if(id)Object.assign(p,data);else db.products.push(data);save();closeModal();render();toast('تم حفظ المنتج')}}
function featureProductPurchase(id){if(db.closes.some(c=>c.date===today))return toast('اليوم مقفل؛ لا يمكن إضافة شراء بتاريخ اليوم');const p=db.products.find(x=>x.id===id);if(!p)return;showModal('شراء مخزون · '+esc(p.name),`<form id="featureBuyForm"><div class="form-grid"><div class="field"><label>الكمية</label><input class="input" name="qty" type="number" min="0.001" step="0.001" required></div><div class="field"><label>تكلفة الوحدة</label><input class="input" name="cost" type="number" min="0" step="0.01" value="${p.cost||0}" required></div><div class="field full"><label>ملاحظة / المورد</label><input class="input" name="note"></div><div class="field"><label>طريقة الدفع</label><select class="select" name="payment"><option value="cash">نقدي</option><option value="card">بطاقة / تحويل</option><option value="wallet">محفظة إلكترونية</option><option value="other">أخرى</option></select></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="featureBuySave">إضافة للمخزون</button>`);document.getElementById('featureBuySave').onclick=()=>{const f=new FormData(document.getElementById('featureBuyForm')),qty=Number(f.get('qty')),cost=Number(f.get('cost'));if(qty<=0||cost<0)return toast('أدخل كمية وتكلفة صحيحتين');p.stock+=qty;p.cost=cost;const expenseId=uid(),amount=qty*cost;db.expenses.push({id:expenseId,title:`شراء ${p.name}`,amount,category:'مخزون منتجات',date:today,payment:String(f.get('payment')||'cash'),note:String(f.get('note')||'')});db.productMovements=db.productMovements||[];db.productMovements.push({id:uid(),productId:p.id,date:today,type:'شراء',quantity:qty,amount,expenseId,note:String(f.get('note')||'')});save();closeModal();render();toast('تم تحديث المخزون وتسجيل المصروف')}}

function featureAttendancePage(){const rows=db.attendance.filter(x=>x.date===today),open=rows.filter(x=>!x.checkOut);return `${pageHead('الحضور والانصراف','سجّل بداية ونهاية الوردية يدويًا أو استورد ملف CSV من جهاز بصمة متوافق.',`<button class="btn" data-fa="attendance-export">تصدير CSV</button><button class="btn" data-fa="attendance-import">استيراد CSV من جهاز البصمة</button><input type="file" id="featureAttendanceFile" accept=".csv,text/csv" hidden>`)}<div class="grid stats-grid">${stat('حضور اليوم',rows.length,'◷',dateFmt(today))}${stat('داخل الوردية',open.length,'●','لم يسجلوا انصرافًا')}${stat('ساعات مكتملة',rows.filter(x=>x.checkOut).reduce((n,x)=>n+featureHours(x),0).toFixed(1),'◴','ساعات مسجلة اليوم')}${stat('مصدر التسجيل',rows.filter(x=>x.source==='بصمة').length,'▣','استيراد بصمة')}</div><div class="card panel"><div class="panel-header"><div><h2>تسجيل سريع</h2><p>تسجيل الحضور والانصراف لفريق العمل</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الحلاق</th><th>الحالة</th><th>دخول</th><th>انصراف</th><th>الساعات</th><th></th></tr></thead><tbody>${featureStaff().map(b=>{const row=rows.find(x=>x.barberId===b.id&&!x.checkOut)||rows.filter(x=>x.barberId===b.id).slice(-1)[0];return `<tr><td>${esc(b.name)}</td><td>${row?.checkOut?'انصرف':row?'في الوردية':'لم يحضر'}</td><td>${row?.checkIn||'—'}</td><td>${row?.checkOut||'—'}</td><td>${row?.checkOut?featureHours(row).toFixed(1):'—'}</td><td>${row&&!row.checkOut?`<button class="btn btn-small btn-primary" data-fa="clock-out" data-id="${b.id}">تسجيل الانصراف</button>`:`<button class="btn btn-small btn-soft" data-fa="clock-in" data-id="${b.id}">تسجيل الحضور</button>`}</td></tr>`}).join('')}</tbody></table></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><h2>سجل الحضور</h2><input class="input" id="attendanceDate" type="date" value="${today}" style="width:160px"></div><div id="attendanceRows">${featureAttendanceTable(db.attendance.filter(x=>x.date===today))}</div><div class="hint">أجهزة البصمة تحتاج ملف CSV بصيغة: اسم الحلاق أو barberId، تاريخ ووقت، ونوع الحركة IN/OUT. لا يوجد ربط مباشر عام بدون تعريف/SDK خاص بالجهاز.</div></div>`}
function featureHours(r){if(!r.checkIn||!r.checkOut)return 0;const [ih,im]=r.checkIn.split(':').map(Number),[oh,om]=r.checkOut.split(':').map(Number);return Math.max(0,(oh*60+om-ih*60-im)/60)}
function featureAttendanceTable(rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>الحلاق</th><th>التاريخ</th><th>دخول</th><th>انصراف</th><th>الساعات</th><th>المصدر</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(barberName(r.barberId))}</td><td>${dateFmt(r.date)}</td><td>${r.checkIn||'—'}</td><td>${r.checkOut||'—'}</td><td>${r.checkOut?featureHours(r).toFixed(1):'—'}</td><td>${esc(r.source||'يدوي')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد سجلات في هذا التاريخ</div>'}
function featureClock(barberId,out=false){let row=db.attendance.find(x=>x.barberId===barberId&&x.date===today&&!x.checkOut);if(out){if(!row)return toast('لا يوجد حضور مفتوح للحلاق');row.checkOut=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date())}else{if(row)return toast('تم تسجيل الحضور بالفعل');row={id:uid(),barberId,date:today,checkIn:new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date()),checkOut:'',source:'يدوي',note:''};db.attendance.push(row)}save();render()}
function featureImportAttendance(file){const rd=new FileReader();rd.onload=()=>{const lines=String(rd.result||'').split(/\r?\n/).filter(Boolean),head=lines.shift().split(',').map(x=>x.trim().toLowerCase()),pick=(r,...keys)=>{const i=head.findIndex(h=>keys.includes(h));return i<0?'':r[i]?.trim()||''};let count=0;for(const line of lines){const r=line.split(',').map(x=>x.trim()),name=pick(r,'barber','barberid','employee','employeeid','name','اسم الحلاق'),dt=pick(r,'datetime','timestamp','time','وقت','التاريخ والوقت'),kind=pick(r,'type','event','direction','نوع الحركة').toLowerCase();const b=featureStaff().find(x=>x.id===name||x.name.toLowerCase()===name.toLowerCase()||x.username?.toLowerCase()===name.toLowerCase());if(!b||!dt)continue;const date=dt.slice(0,10),time=dt.slice(11,16),out=/out|check.?out|خروج/.test(kind);let a=db.attendance.find(x=>x.barberId===b.id&&x.date===date&&!x.checkOut);if(out&&a)a.checkOut=time;else if(!out){a={id:uid(),barberId:b.id,date,checkIn:time,checkOut:'',source:'بصمة',note:''};db.attendance.push(a)}if(a)count++}save();render();toast(`تم استيراد ${count} حركة حضور`)};rd.readAsText(file,'utf-8')}function featurePayrollPage(){const month=document.getElementById('payrollMonth')?.value||today.slice(0,7),records=db.payroll.filter(x=>x.period===month),totalDue=featureStaff().reduce((n,b)=>n+featurePayrollCalc(b,month).due,0),paid=featureStaff().reduce((n,b)=>n+featurePayrollCalc(b,month).paid,0);return `${pageHead('الرواتب والعمولات','احسب الراتب الأساسي والعمولة والسلف والمكافآت والخصومات واطبع كشف الراتب.',`<button class="btn" data-fa="payroll-export">تصدير CSV</button><button class="btn btn-primary" data-fa="payroll-adjust">＋ إضافة سلفة أو تعديل</button>`)}<div class="grid stats-grid">${stat('الشهر',month,'◷','الفترة المحددة')}${stat('إجمالي المستحق',money(totalDue),'◈','بعد الإضافات والخصومات')}${stat('إجمالي المدفوع',money(paid),'✓','مسجل في الرواتب')}${stat('المتبقي',money(Math.max(0,totalDue-paid)),'↙','قابل للصرف')}</div><div class="card panel"><div class="panel-header"><div><h2>كشف رواتب الفريق</h2><p>حدد راتبًا أساسيًا لكل حلاق، وتضاف عمولة المبيعات المسجلة.</p></div><input class="input" id="payrollMonth" type="month" value="${month}" style="width:150px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الحلاق</th><th>أساسي</th><th>عمولة</th><th>سلف</th><th>مكافآت</th><th>خصومات</th><th>المستحق</th><th>مدفوع</th><th>متبقي</th><th></th></tr></thead><tbody>${featureStaff().map(b=>{const x=featurePayrollCalc(b,month);return `<tr><td><strong>${esc(b.name)}</strong></td><td>${money(x.base)}</td><td>${money(x.commission)}</td><td>${money(x.advance)}</td><td>${money(x.incentive)}</td><td>${money(x.deduction)}</td><td>${money(x.due)}</td><td>${money(x.paid)}</td><td>${money(Math.max(0,x.due-x.paid))}</td><td><button class="btn btn-small" data-fa="salary-base" data-id="${b.id}">الأساسي</button> <button class="btn btn-small btn-primary" data-fa="salary-pay" data-id="${b.id}">صرف</button> <button class="btn btn-small btn-soft" data-fa="salary-slip" data-id="${b.id}">كشف</button></td></tr>`}).join('')}</tbody></table></div></div><div class="card panel" style="margin-top:15px"><div class="panel-header"><h2>حركات الرواتب</h2></div>${records.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>الحلاق</th><th>الفترة</th><th>نوع الحركة</th><th>المبلغ</th><th>تاريخ الصرف</th><th>ملاحظة</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(barberName(r.barberId))}</td><td>${r.period}</td><td>${r.advance?'سلفة':r.incentive?'مكافأة':r.deduction?'خصم':r.paid?'صرف راتب':'راتب'}</td><td>${money(r.advance||r.incentive||r.deduction||r.paid||r.baseSalary)}</td><td>${r.paymentDate||'—'}</td><td>${esc(r.note||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد حركات لهذا الشهر</div>'}</div>`}
function featurePayrollCalc(b,period){const rows=db.sales.filter(s=>s.barberId===b.id&&s.date.startsWith(period)),commission=rows.reduce((n,s)=>n+commissionFor(s),0),tx=db.payroll.filter(x=>x.barberId===b.id&&x.period===period);const base=Number(b.baseSalary)||0,advance=tx.reduce((n,x)=>n+(Number(x.advance)||0),0),incentive=tx.reduce((n,x)=>n+(Number(x.incentive)||0),0),deduction=tx.reduce((n,x)=>n+(Number(x.deduction)||0),0),paid=tx.reduce((n,x)=>n+(Number(x.paid)||0),0)+barberPeriodPaid(b.id,period);return{base,commission,advance,incentive,deduction,paid,due:Math.max(0,base+commission+incentive-advance-deduction)}}
function featurePayrollAdjustment(){showModal('إضافة حركة راتب',`<form id="featurePayrollForm"><div class="form-grid"><div class="field"><label>الحلاق</label><select class="select" name="barberId">${featureStaff().map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>الشهر</label><input class="input" name="period" type="month" value="${today.slice(0,7)}"></div><div class="field"><label>نوع الحركة</label><select class="select" name="kind"><option value="advance">سلفة</option><option value="incentive">مكافأة</option><option value="deduction">خصم</option></select></div><div class="field"><label>المبلغ</label><input class="input" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field full"><label>ملاحظة</label><input class="input" name="note"></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="featurePayrollSave">حفظ الحركة</button>`);document.getElementById('featurePayrollSave').onclick=()=>{const f=new FormData(document.getElementById('featurePayrollForm')),x={id:uid(),barberId:f.get('barberId'),period:f.get('period'),advance:0,incentive:0,deduction:0,paid:0,note:String(f.get('note')||'')};x[f.get('kind')]=Number(f.get('amount'))||0;db.payroll.push(x);save();closeModal();render()}}
function featureSetBaseSalary(id){const b=featureStaff().find(x=>x.id===id);if(!b)return;const value=prompt(`الراتب الأساسي الشهري لـ ${b.name}`,String(b.baseSalary||0));if(value===null)return;if(!Number.isFinite(Number(value))||Number(value)<0)return toast('قيمة راتب غير صحيحة');b.baseSalary=Number(value);if(db.barbers.some(x=>x.id===id)){const barber=db.barbers.find(x=>x.id===id);barber.baseSalary=Number(value)}else{const detail=db.employeeDetails.find(x=>x.employeeId===id);if(detail)detail.baseSalary=Number(value);else db.employeeDetails.push({employeeId:id,baseSalary:Number(value),name:b.name})}save();render()}
function featurePaySalary(id){if(db.closes.some(c=>c.date===today))return toast('اليوم مقفل؛ لا يمكن تسجيل صرف جديد');const period=document.getElementById('payrollMonth')?.value||today.slice(0,7),b=featureStaff().find(x=>x.id===id),x=featurePayrollCalc(b,period),remaining=Math.max(0,x.due-x.paid);if(!remaining)return toast('لا يوجد مبلغ متبقٍ للصرف');showModal('صرف راتب · '+esc(b.name),`<div class="modal-note">المتبقي عن ${period}: <b>${money(remaining)}</b></div><div class="field"><label>المبلغ المدفوع</label><input id="featurePayAmount" class="input" type="number" min="0.01" max="${remaining}" step="0.01" value="${remaining}"></div><div class="field" style="margin-top:10px"><label>طريقة الدفع</label><select id="featurePayMethod" class="select"><option value="cash">نقدي</option><option value="card">تحويل / بطاقة</option></select></div>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="featurePayConfirm">تأكيد الصرف</button>`);document.getElementById('featurePayConfirm').onclick=()=>{const amount=Number(document.getElementById('featurePayAmount').value);if(!Number.isFinite(amount)||amount<=0||amount>remaining)return toast('أدخل مبلغًا ضمن المتبقي');db.payroll.push({id:uid(),barberId:id,period,paid:amount,paymentDate:today,note:`صرف ${document.getElementById('featurePayMethod').value}`});db.payouts.push({id:uid(),date:today,period,barberId:id,amount,payment:document.getElementById('featurePayMethod').value,note:'صرف راتب'});save();closeModal();render();toast('تم تسجيل صرف الراتب')}}
function featureSalarySlip(id){const period=document.getElementById('payrollMonth')?.value||today.slice(0,7),b=featureStaff().find(x=>x.id===id),x=featurePayrollCalc(b,period);featurePrint(`<h1>${esc(db.settings.shop)}</h1><h2>كشف راتب</h2><p>الحلاق: ${esc(b.name)} — الشهر: ${period}</p><table><tr><td>الراتب الأساسي</td><td>${money(x.base)}</td></tr><tr><td>العمولات</td><td>${money(x.commission)}</td></tr><tr><td>المكافآت</td><td>${money(x.incentive)}</td></tr><tr><td>السلف</td><td>-${money(x.advance)}</td></tr><tr><td>الخصومات</td><td>-${money(x.deduction)}</td></tr><tr><th>المستحق</th><th>${money(x.due)}</th></tr><tr><td>المدفوع</td><td>${money(x.paid)}</td></tr><tr><th>المتبقي</th><th>${money(Math.max(0,x.due-x.paid))}</th></tr></table>`)}

function featureOffersPage(){return `${pageHead('العروض والخصومات','أنشئ عروضًا بنسبة أو مبلغ ثابت مع تاريخ صلاحية وحد أدنى للفاتورة.',`<button class="btn btn-primary" data-fa="offer-add">＋ عرض جديد</button>`)}<div class="card panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>العرض</th><th>نوع الخصم</th><th>القيمة</th><th>الحد الأدنى</th><th>الصلاحية</th><th>الحالة</th><th></th></tr></thead><tbody>${db.offers.length?db.offers.map(o=>`<tr><td><strong>${esc(o.name)}</strong></td><td>${o.type==='fixed'?'مبلغ ثابت':'نسبة'}</td><td>${o.type==='fixed'?money(o.value):o.value+'%'}</td><td>${money(o.minTotal||0)}</td><td>${o.start||'دائم'} — ${o.end||'مفتوح'}</td><td>${o.active?'نشط':'موقوف'}</td><td><button class="btn btn-small" data-fa="offer-edit" data-id="${o.id}">تعديل</button> <button class="btn btn-small" data-fa="offer-toggle" data-id="${o.id}">${o.active?'إيقاف':'تفعيل'}</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">لا توجد عروض. العروض النشطة ستظهر على الكاشير عند تحقق الشروط.</td></tr>'}</tbody></table></div></div><div class="hint" style="margin-top:12px">يُحسب الخصم قبل الضريبة، ويسجل رقم العرض على الفاتورة والتقرير.</div>`}
function featureOfferModal(id){const o=db.offers.find(x=>x.id===id)||{name:'',type:'percent',value:0,start:'',end:'',minTotal:0,active:true};showModal(id?'تعديل عرض':'إضافة عرض',`<form id="featureOfferForm"><div class="form-grid"><div class="field full"><label>اسم العرض</label><input class="input" name="name" required value="${esc(o.name)}"></div><div class="field"><label>نوع الخصم</label><select class="select" name="type"><option value="percent" ${o.type==='percent'?'selected':''}>نسبة مئوية</option><option value="fixed" ${o.type==='fixed'?'selected':''}>مبلغ ثابت</option></select></div><div class="field"><label>القيمة</label><input class="input" name="value" type="number" min="0" step="0.01" value="${o.value}"></div><div class="field"><label>من تاريخ</label><input class="input" name="start" type="date" value="${o.start||''}"></div><div class="field"><label>إلى تاريخ</label><input class="input" name="end" type="date" value="${o.end||''}"></div><div class="field"><label>حد أدنى للفاتورة</label><input class="input" name="minTotal" type="number" min="0" value="${o.minTotal||0}"></div><div class="field"><label><input type="checkbox" name="active" ${o.active?'checked':''}> نشط</label></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="featureOfferSave">حفظ</button>`);document.getElementById('featureOfferSave').onclick=()=>{const f=new FormData(document.getElementById('featureOfferForm')),x={id:id||uid(),name:String(f.get('name')).trim(),type:f.get('type'),value:Number(f.get('value'))||0,start:String(f.get('start')||''),end:String(f.get('end')||''),minTotal:Number(f.get('minTotal'))||0,active:f.has('active')};if(!x.name)return toast('أدخل اسم العرض');if(id)Object.assign(o,x);else db.offers.push(x);save();closeModal();render()}}

function featureRemindersPage(){featureCheckReminders();const appts=db.appointments.filter(a=>a.status==='booked'&&a.date>=today).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `${pageHead('التذكيرات','تذكيرات محلية تعمل أثناء فتح البرنامج، ورسالة واتساب تُفتح للمراجعة والإرسال اليدوي.',`<button class="btn" data-fa="notifications-enable">تفعيل إشعارات سطح المكتب</button>`)}<div class="card panel"><div class="panel-header"><div><h2>المواعيد القادمة</h2><p>تظهر هنا المواعيد المحجوزة للعملاء</p></div><span class="tag">${appts.length} موعد</span></div>${appts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>الموعد</th><th>العميل</th><th>الهاتف</th><th>الخدمة</th><th>الحلاق</th><th>تذكير</th><th></th></tr></thead><tbody>${appts.map(a=>`<tr><td>${dateFmt(a.date)} · ${esc(a.time)}</td><td>${esc(a.client)}</td><td>${esc(a.phone||'—')}</td><td>${esc(serviceName(a.serviceId))}</td><td>${esc(barberName(a.barberId))}</td><td>${a.reminderAt?'محدد':'عند فتح صفحة التذكيرات'}</td><td><button class="btn btn-small" data-fa="reminder-set" data-id="${a.id}">تحديد التذكير</button> <button class="btn btn-small btn-soft" data-fa="reminder-wa" data-id="${a.id}">واتساب</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد مواعيد قادمة</div>'}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><h2>قائمة التذكيرات</h2></div>${db.reminders.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ والوقت</th><th>العميل</th><th>القناة</th><th>الحالة</th><th>ملاحظة</th></tr></thead><tbody>${db.reminders.map(r=>`<tr><td>${dateFmt(r.date)} · ${r.time}</td><td>${esc(r.client)}</td><td>${r.channel==='whatsapp'?'WhatsApp':'محلي'}</td><td>${r.status==='done'?'تم':'مجدول'}</td><td>${esc(r.note||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد تذكيرات إضافية</div>'}<div class="hint">التذكير المحلي يحتاج بقاء التطبيق مفتوحًا. إرسال واتساب لا يتم تلقائيًا دون إنترنت أو ربط رسمي؛ الزر يفتح المحادثة فقط.</div></div>`}
function featureCheckReminders(){if(featureReminderTimer)return;featureReminderTimer=setInterval(()=>{if(!passwordUnlocked)return;const now=new Date();for(const r of db.reminders){if(r.status==='pending'&&new Date(`${r.date}T${r.time}`)<=now){r.status='done';if('Notification'in window&&Notification.permission==='granted')new Notification('تذكير كربيجي',{body:`${r.client} · ${r.note||'موعد عميل'}`});else toast(`تذكير: ${r.client} · ${r.note||'موعد'}`);save();if(page==='reminders')render()}}},60000)}
function featureEnableNotifications(){if(!('Notification'in window))return toast('إشعارات سطح المكتب غير مدعومة في هذا المتصفح');Notification.requestPermission().then(x=>toast(x==='granted'?'تم تفعيل الإشعارات':'لم يتم السماح بالإشعارات'))}
function featureReminderSet(id){const a=db.appointments.find(x=>x.id===id);if(!a)return;const at=prompt('وقت التذكير بصيغة YYYY-MM-DD HH:MM',`${a.date} ${a.time}`);if(!at)return;const [date,time]=at.split(' ');if(!date||!time)return toast('صيغة التاريخ أو الوقت غير صحيحة');a.reminderAt=at;db.reminders=db.reminders.filter(r=>!(r.appointmentId===a.id&&r.status==='pending'));db.reminders.push({id:uid(),appointmentId:a.id,client:a.client,phone:a.phone,date,time,channel:'local',status:'pending',note:`موعد ${serviceName(a.serviceId)}`});save();render()}
function featureReminderWhatsApp(id){const a=db.appointments.find(x=>x.id===id);if(!a?.phone)return toast('أضف رقم هاتف العميل أولًا');let phone=a.phone.replace(/\D/g,'');if(phone.startsWith('0'))phone='20'+phone.slice(1);const msg=encodeURIComponent(`تذكير بموعدك في ${db.settings.shop} يوم ${a.date} الساعة ${a.time}`);window.open(`https://wa.me/${phone}?text=${msg}`,'_blank','noopener');}

function featureAppointmentsPage(){const base=new Date(`${featureAppointmentDate}T12:00:00`),start=new Date(base),end=new Date(base);if(featureAppointmentView==='week'){start.setDate(base.getDate()-((base.getDay()+6)%7));end.setDate(start.getDate()+6)}else if(featureAppointmentView==='month'){start.setDate(1);end.setMonth(start.getMonth()+1,0)}const lo=iso(start),hi=iso(end),rows=db.appointments.filter(a=>a.status!=='waitlist'&&a.date>=lo&&a.date<=hi).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),wait=db.appointments.filter(a=>a.status==='waitlist');return `${pageHead('المواعيد وقائمة الانتظار','عرض يومي أو أسبوعي أو شهري، مع إدارة دور العملاء.',`<button class="btn btn-primary" data-fa="appointment-add">＋ حجز جديد</button><button class="btn" data-fa="appointment-wait">＋ قائمة الانتظار</button>`)}<div class="card panel"><div class="panel-header"><div><h2>المواعيد</h2><p>${dateFmt(lo)} — ${dateFmt(hi)}</p></div><div class="inline-add"><select class="select" id="appointmentView" style="width:110px"><option value="day" ${featureAppointmentView==='day'?'selected':''}>يومي</option><option value="week" ${featureAppointmentView==='week'?'selected':''}>أسبوعي</option><option value="month" ${featureAppointmentView==='month'?'selected':''}>شهري</option></select><input class="input" id="appointmentDate" type="date" value="${featureAppointmentDate}" style="width:150px"></div></div>${featureAppointmentTable(rows)}</div><div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>قائمة الانتظار</h2><p>العملاء المنتظرون بدون موعد محدد</p></div><span class="tag">${wait.length} عميل</span></div>${featureAppointmentTable(wait)}</div>`}
function featureAppointmentTable(rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>التاريخ والوقت</th><th>العميل</th><th>الخدمة</th><th>الحلاق</th><th>الهاتف</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${a.status==='waitlist'?'بدون موعد':`${dateFmt(a.date)} · ${esc(a.time)}`}</td><td>${esc(a.client)}</td><td>${esc(serviceName(a.serviceId))}</td><td>${esc(barberName(a.barberId))}</td><td>${esc(a.phone||'—')}</td><td>${a.status==='completed'?'مكتمل':a.status==='cancelled'?'ملغي':a.status==='in_service'?'داخل الجلسة':a.status==='waitlist'?'انتظار':'قادم'}</td><td>${a.status==='booked'?`<button class="btn btn-small btn-soft" data-fa="appointment-session" data-id="${a.id}">بدء جلسة</button>`:''} <button class="btn btn-small" data-fa="appointment-edit" data-id="${a.id}">تعديل</button> <button class="btn btn-small" data-fa="appointment-delete" data-id="${a.id}">حذف</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد مواعيد في الفترة</div>'}
const featureBaseAppointmentTable=featureAppointmentTable;
featureAppointmentTable=function(rows){return featureBaseAppointmentTable(rows).replace(/<button class="btn btn-small" data-fa="appointment-edit" data-id="([^"]+)">تعديل<\/button>/g,(html,id)=>db.appointments.find(a=>a.id===id)?.status==='in_service'?`<button class="btn btn-small btn-soft" data-fa="appointment-checkout" data-id="${id}">إلى الفاتورة</button> ${html}`:html)};
function featureAppointmentCheckout(id){const a=db.appointments.find(x=>x.id===id);if(!a)return;featureActiveAppointmentId=id;a.status='in_service';const s=db.services.find(x=>x.id===a.serviceId);cart=s?[{serviceId:s.id,name:s.name,price:Number(s.price)}]:[];page='cashier';render();document.getElementById('clientName').value=a.client;document.getElementById('clientPhone').value=a.phone||'';document.getElementById('saleBarber').value=a.barberId;featureRefreshCart();save()}
const featureOriginalAction=featureAction;
featureAction=function(kind,b){if(kind==='appointment-session'||kind==='appointment-checkout')return featureAppointmentCheckout(b.dataset.id);return featureOriginalAction(kind,b)};
function featureAppointmentModal(id,waitlist=false){const a=db.appointments.find(x=>x.id===id)||{client:'',phone:'',date:today,time:'12:00',serviceId:db.services[0]?.id||'',barberId:activeBarbers()[0]?.id||'',status:waitlist?'waitlist':'booked',notes:''};showModal(id?'تعديل الموعد':waitlist?'إضافة لقائمة الانتظار':'حجز موعد',`<form id="featureAppointmentForm"><div class="form-grid"><div class="field full"><label>اسم العميل *</label><input class="input" name="client" required value="${esc(a.client)}"></div><div class="field"><label>الهاتف</label><input class="input" name="phone" value="${esc(a.phone||'')}"></div><div class="field"><label>التاريخ</label><input class="input" name="date" type="date" value="${a.date||today}"></div><div class="field"><label>الوقت</label><input class="input" name="time" type="time" value="${a.time||'12:00'}"></div><div class="field"><label>الخدمة</label><select class="select" name="serviceId">${db.services.map(s=>`<option value="${s.id}" ${s.id===a.serviceId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>الحلاق</label><select class="select" name="barberId">${activeBarbers().map(b=>`<option value="${b.id}" ${b.id===a.barberId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="field full"><label>ملاحظات</label><input class="input" name="notes" value="${esc(a.notes||'')}"></div></div></form>`,`<button class="btn" onclick="closeModal()">إلغاء</button><button class="btn btn-primary" id="featureAppointmentSave">حفظ</button>`);document.getElementById('featureAppointmentSave').onclick=()=>{const f=new FormData(document.getElementById('featureAppointmentForm'));if(!String(f.get('client')||'').trim())return toast('أدخل اسم العميل');const data={id:a.id||uid(),client:String(f.get('client')).trim(),phone:String(f.get('phone')||''),date:waitlist?'':String(f.get('date')||today),time:waitlist?'':String(f.get('time')||'12:00'),serviceId:String(f.get('serviceId')||''),barberId:String(f.get('barberId')||''),status:waitlist?'waitlist':a.status==='waitlist'?'booked':a.status||'booked',notes:String(f.get('notes')||'')};if(id)Object.assign(a,data);else db.appointments.push(data);db.reminders=db.reminders.filter(r=>!(r.appointmentId===data.id&&r.status==='pending'));if(data.status==='booked'&&data.date&&data.time&&!db.reminders.some(r=>r.appointmentId===data.id&&r.status==='pending')){const apptTime=new Date(`${data.date}T${data.time}`),at=new Date(apptTime.getTime()-30*60000);db.reminders.push({id:uid(),appointmentId:data.id,client:data.client,phone:data.phone,date:iso(at),time:new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(at),channel:'local',status:'pending',note:`تذكير قبل موعد ${serviceName(data.serviceId)}`})}save();closeModal();render();toast('تم حفظ الموعد')}}
function featureCustomersPage(){const rows=customerGroups().map(c=>({...c,points:featureCustomerPoints(c.phone)}));return `${pageHead('العملاء ونقاط الولاء','ملفات العملاء وسجل الزيارات والإنفاق والنقاط المكتسبة.',`<span class="tag">كل ${db.settings.loyaltyEarnRate} ${esc(db.settings.currency)} = نقطة</span>`)}<div class="grid stats-grid" style="grid-template-columns:repeat(3,1fr)">${stat('العملاء المسجلون',rows.length,'♙','حسب الهاتف والاسم')}${stat('إجمالي النقاط',rows.reduce((n,c)=>n+c.points,0),'★','النقاط غير المستبدلة')}${stat('إنفاق العملاء',money(rows.reduce((n,c)=>n+salesTotal(c.sales),0)),'◈','كل الفترات')}</div><div class="card panel"><div class="panel-header"><div><h2>ملفات العملاء</h2><p>اضغط على سجل الزيارات لمراجعة النقاط والفواتير</p></div><input id="customerSearch" class="input" placeholder="ابحث بالاسم أو الهاتف" style="width:210px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>العميل</th><th>الهاتف</th><th>الزيارات</th><th>الإنفاق</th><th>النقاط</th><th>آخر زيارة</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr class="history-row"><td>${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${c.sales.length}</td><td>${money(salesTotal(c.sales))}</td><td>${c.points}</td><td>${dateFmt(c.sales.reduce((d,s)=>s.date>d?s.date:d,''))}</td><td><button class="btn btn-small" data-fa="customer-history" data-key="${esc(c.key)}">التفاصيل</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">تظهر ملفات العملاء بعد تسجيل أول زيارة</td></tr>'}</tbody></table></div></div>`}

function featureCashierPage(){const isClosed=db.closes.some(c=>c.date===today),subtotal=cart.reduce((n,x)=>n+x.price,0),offers=db.offers.filter(o=>o.active!==false&&(!o.start||today>=o.start)&&(!o.end||today<=o.end));return `${pageHead('الكاشير والفواتير','أضف خدمات ومنتجات، طبّق عرضًا أو نقاطًا، ثم اطبع فاتورة.',isClosed?'<span class="tag red">الكاشير مغلق اليوم</span>':`<button class="btn" data-action="close-day">▣ إقفال اليوم</button>`)}<div class="split-layout"><div><div class="card panel"><div class="panel-header"><div><h2>الخدمات والمنتجات</h2><p>اضغط لإضافتها إلى الفاتورة</p></div><input class="input" id="serviceSearch" placeholder="ابحث" style="width:180px"></div><h3 class="muted">الخدمات</h3><div class="cashier-services">${db.services.filter(s=>s.active).map(s=>`<button class="service-tile" data-feature-service="${s.id}"><span class="tile-icon">✦</span><strong>${esc(s.name)}</strong><small>${money(s.price)}</small></button>`).join('')}</div><h3 class="muted">المنتجات</h3><div class="cashier-services">${db.products.filter(p=>p.active!==false&&p.stock>0).map(p=>`<button class="service-tile" data-feature-product="${p.id}"><span class="tile-icon">▣</span><strong>${esc(p.name)}</strong><small>${money(p.price)} · متاح ${p.stock}</small></button>`).join('')||'<div class="empty-state">لا توجد منتجات متاحة</div>'}</div></div><div class="card panel" style="margin-top:14px"><div class="panel-header"><h2>آخر الفواتير</h2></div>${featureSalesRows(todaySales())}</div></div><div class="card panel order-card"><div class="panel-header"><div><h2>جلسة / فاتورة جديدة</h2><p>بيانات العميل والخدمة والخصم</p></div><button class="text-link" data-fa="cart-clear">تفريغ</button></div><div class="form-grid"><div class="field"><label>اسم العميل</label><input id="clientName" class="input" placeholder="عميل نقدي"></div><div class="field"><label>رقم الهاتف</label><input id="clientPhone" class="input" placeholder="01xxxxxxxxx"></div><div class="field"><label>الحلاق</label><select id="saleBarber" class="select"><option value="">اختر الحلاق</option>${activeBarbers().map(b=>`<option value="${b.id}">${esc(b.name)} · ${b.commission}%</option>`).join('')}</select></div><div class="field"><label>الكرسي</label><select id="saleChair" class="select"><option value="">اختر الكرسي</option>${db.chairs.filter(c=>c.active).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div></div><div id="featureCart">${featureCartRows()}</div><div class="field"><label>العرض</label><select id="saleOffer" class="select"><option value="">بدون عرض</option>${offers.map(o=>`<option value="${o.id}">${esc(o.name)} · ${o.type==='fixed'?money(o.value):o.value+'%'}</option>`).join('')}</select></div><div class="form-grid" style="margin-top:8px"><div class="field"><label>خصم إضافي %</label><input id="saleDiscount" class="input" type="number" min="0" max="100" value="0"></div><div class="field"><label>استبدال نقاط</label><input id="saleRedeemPoints" class="input" type="number" min="0" value="0"></div></div><div class="order-total"><span>قبل الخصم</span><strong id="featureSubtotal">${money(subtotal)}</strong></div><div class="order-total"><span>ضريبة ${Number(db.settings.taxRate)||0}% · الإجمالي</span><strong id="featureTotal">${money(subtotal)}</strong></div><div class="field"><label>طريقة الدفع</label><select id="salePayment" class="select"><option value="cash">نقدي</option><option value="card">بطاقة</option><option value="wallet">محفظة إلكترونية</option><option value="other">أخرى</option></select></div><button class="btn btn-primary" data-fa="checkout" ${isClosed?'disabled':''} style="width:100%;margin-top:14px">تأكيد البيع · ${money(subtotal)}</button><div class="hint">النقاط تُضاف تلقائيًا للعميل المسجل بالهاتف.</div></div></div>`}
function featureCartRows(){return cart.length?cart.map((i,n)=>`<div class="order-row"><div>${esc(i.name)}<small>${i.productId?'منتج':'خدمة'} · ${money(i.price)}</small></div><b>${money(i.price)}</b><button class="remove-line" data-feature-remove="${n}">×</button></div>`).join(''):'<div class="empty-state">الفاتورة فارغة</div>'}
function featureTotals(){const sub=cart.reduce((n,x)=>n+x.price,0),offer=db.offers.find(o=>o.id===document.getElementById('saleOffer')?.value&&o.active!==false&&(!o.start||today>=o.start)&&(!o.end||today<=o.end)&&sub>=Number(o.minTotal||0)),pct=Math.min(100,Number(document.getElementById('saleDiscount')?.value)||0),offerDiscount=offer?(offer.type==='fixed'?Number(offer.value):sub*Number(offer.value)/100):0,manual=sub*pct/100,points=Number(document.getElementById('saleRedeemPoints')?.value)||0,redeemed=Math.min(featureCustomerPoints(document.getElementById('clientPhone')?.value),points),pointsValue=redeemed*(Number(db.settings.loyaltyPointValue)||0),discount=Math.min(sub,offerDiscount+manual+pointsValue),taxBase=Math.max(0,sub-discount),tax=taxBase*(Number(db.settings.taxRate)||0)/100;return{sub,discount,tax,total:taxBase+tax,redeemed}}
function featureRefreshCart(){const c=document.getElementById('featureCart');if(c){c.innerHTML=featureCartRows();c.querySelectorAll('[data-feature-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.featureRemove),1);featureRefreshCart()})}const t=featureTotals();const sub=document.getElementById('featureSubtotal'),total=document.getElementById('featureTotal'),btn=document.querySelector('[data-fa="checkout"]');if(sub)sub.textContent=money(t.sub);if(total)total.textContent=money(t.total);if(btn)btn.textContent='تأكيد البيع · '+money(t.total)}
function featureCheckout(){if(db.closes.some(c=>c.date===today))return toast('الكاشير مغلق اليوم');if(!cart.length)return toast('أضف خدمة أو منتجًا أولًا');const barberId=document.getElementById('saleBarber').value,chairId=document.getElementById('saleChair').value,hasServices=cart.some(x=>x.serviceId);if(hasServices&&!barberId)return toast('اختر الحلاق');if(hasServices&&!chairId)return toast('اختر الكرسي');const totals=featureTotals(),productNeeds=new Map();for(const i of cart)if(i.productId)productNeeds.set(i.productId,(productNeeds.get(i.productId)||0)+(i.quantity||1));for(const [id,q] of productNeeds){const p=db.products.find(x=>x.id===id);if(!p||p.stock<q)return toast(`رصيد ${p?.name||'المنتج'} غير كافٍ`)}const lines=cart.map(i=>({serviceId:i.serviceId||'',productId:i.productId||'',price:Number(i.price)||0,quantity:i.quantity||1})),s={id:uid(),invoiceNo:'H-'+String(Date.now()).slice(-8),date:today,createdAt:new Date().toISOString(),client:document.getElementById('clientName').value.trim()||'عميل نقدي',clientPhone:document.getElementById('clientPhone').value.trim(),barberId,chairId,payment:document.getElementById('salePayment').value,items:lines,subtotal:totals.sub,discount:Number(document.getElementById('saleDiscount').value)||0,discountAmount:totals.discount,taxRate:Number(db.settings.taxRate)||0,tax:totals.tax,total:totals.total,commission:db.barbers.find(b=>b.id===barberId)?.commission??db.settings.commission,offerId:document.getElementById('saleOffer').value,appointmentId:featureActiveAppointmentId||'',pointsRedeemed:totals.redeemed,pointsEarned:document.getElementById('clientPhone').value?Math.floor(Math.max(0,totals.total)/(Number(db.settings.loyaltyEarnRate)||10)):0,customers:1};const check=canConsumeForSale(lines.filter(x=>x.serviceId));if(!check.ok)return toast(check.message);consumeForSale(lines.filter(x=>x.serviceId),s);for(const [id,q] of productNeeds){const p=db.products.find(x=>x.id===id);p.stock-=q;db.productMovements=db.productMovements||[];db.productMovements.push({id:uid(),productId:id,date:today,type:'بيع',quantity:q,amount:p.cost*q,saleId:s.id,note:`فاتورة ${s.invoiceNo}`})}db.sales.push(s);if(featureActiveAppointmentId){const appt=db.appointments.find(a=>a.id===featureActiveAppointmentId);if(appt)appt.status='completed';featureActiveAppointmentId=''}save();cart=[];render();featurePrintInvoice(s.id);toast(`تم تسجيل الفاتورة ${s.invoiceNo}`)}
function featureSalesRows(rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>الوقت / الفاتورة</th><th>العميل</th><th>المنتجات والخدمات</th><th>الحلاق</th><th>الدفع</th><th>الإجمالي</th><th></th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(s=>`<tr><td>${timeFmt(s.createdAt)}<small style="display:block">${featureInvoiceNo(s)}</small></td><td>${esc(s.client||'عميل نقدي')}</td><td>${s.items.map(i=>esc(featureSaleLine(i))).join('، ')}</td><td>${esc(barberName(s.barberId))}</td><td>${s.payment==='cash'?'نقدي':s.payment==='card'?'بطاقة':s.payment==='wallet'?'محفظة':'أخرى'}</td><td>${money(s.total)}</td><td><button class="btn btn-small" data-fa="invoice-print" data-id="${s.id}">فاتورة</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد فواتير حتى الآن</div>'}
function featurePrintInvoice(id){const s=db.sales.find(x=>x.id===id);if(!s)return;const rows=(s.items||[]).map(i=>`<tr><td>${esc(featureSaleLine(i))}</td><td>${i.quantity||1}</td><td>${money(i.price)}</td></tr>`).join('');featurePrint(`<h1>${esc(db.settings.shop)}</h1><h2>فاتورة بيع</h2><p>رقم: ${featureInvoiceNo(s)} · التاريخ: ${dateFmt(s.date)} ${timeFmt(s.createdAt)}</p><p>العميل: ${esc(s.client||'عميل نقدي')} · الحلاق: ${esc(barberName(s.barberId))}</p><table><thead><tr><th>الخدمة / المنتج</th><th>الكمية</th><th>السعر</th></tr></thead><tbody>${rows}</tbody></table><p>قبل الخصم: ${money(s.subtotal??s.total)}</p><p>الخصم: -${money(s.discountAmount)}</p><p>الضريبة: ${money(s.tax)}</p><h2>الإجمالي: ${money(s.total)}</h2><p>الدفع: ${featurePaymentLabel(s.payment)}</p><p>شكرًا لزيارتكم</p>`)}
function featurePrint(html){const w=window.open('','_blank','width=720,height=850');if(!w)return toast('اسمح بفتح نافذة الطباعة');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>كربيجي</title><style>body{font-family:Tahoma,Arial;padding:30px;color:#222}h1,h2{text-align:center}table{width:100%;border-collapse:collapse;margin:22px 0}td,th{border:1px solid #ddd;padding:10px;text-align:right}@media print{button{display:none}}</style><body>${html}<button onclick="window.print()">طباعة</button><script>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}

function featureWire(){const p=document.getElementById('page');p.querySelectorAll('[data-fa]').forEach(b=>b.addEventListener('click',()=>featureAction(b.dataset.fa,b)));p.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));p.querySelectorAll('[data-feature-service]').forEach(b=>b.onclick=()=>{if(!db.closes.some(c=>c.date===today)){const s=db.services.find(x=>x.id===b.dataset.featureService);cart.push({serviceId:s.id,name:s.name,price:Number(s.price)});featureRefreshCart()}});p.querySelectorAll('[data-feature-product]').forEach(b=>b.onclick=()=>{if(!db.closes.some(c=>c.date===today)){const x=db.products.find(x=>x.id===b.dataset.featureProduct);cart.push({productId:x.id,name:x.name,price:Number(x.price),quantity:1});featureRefreshCart()}});const phone=document.getElementById('clientPhone');if(phone)phone.oninput=featureRefreshCart;for(const id of ['saleOffer','saleDiscount','saleRedeemPoints']){const el=document.getElementById(id);if(el)el.oninput=featureRefreshCart,el.onchange=featureRefreshCart}const apptDate=document.getElementById('appointmentDate');if(apptDate)apptDate.onchange=()=>{featureAppointmentDate=apptDate.value||today;render()};const apptView=document.getElementById('appointmentView');if(apptView)apptView.onchange=()=>{featureAppointmentView=apptView.value;render()};const attDate=document.getElementById('attendanceDate');if(attDate)attDate.onchange=()=>{const d=attDate.value||today;document.getElementById('attendanceRows').innerHTML=featureAttendanceTable(db.attendance.filter(x=>x.date===d))};const payrollMonth=document.getElementById('payrollMonth');if(payrollMonth)payrollMonth.onchange=render;const itemSearch=document.getElementById('serviceSearch');if(itemSearch)itemSearch.oninput=()=>{const q=itemSearch.value.toLowerCase();document.querySelectorAll('[data-feature-service],[data-feature-product]').forEach(b=>b.hidden=!b.innerText.toLowerCase().includes(q))};const search=document.getElementById('customerSearch');if(search)search.oninput=()=>{const q=search.value.toLowerCase();document.querySelectorAll('.history-row').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q))};const productSearch=document.getElementById('productSearch');if(productSearch)productSearch.oninput=()=>{const q=productSearch.value.toLowerCase();document.querySelectorAll('[data-product-row]').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q))};const importFile=document.getElementById('featureAttendanceFile');if(importFile)importFile.onchange=()=>importFile.files[0]&&featureImportAttendance(importFile.files[0]);const restoreFile=document.getElementById('restoreFile');if(restoreFile)restoreFile.onchange=restoreBackup;featureApplyLocale(p)}
function featureAction(kind,b){const id=b.dataset.id;switch(kind){case'product-add':return featureProductModal();case'product-edit':return featureProductModal(id);case'product-buy':return featureProductPurchase(id);case'export-products':return featureCsv('products',db.products.map(p=>[p.name,p.sku,p.barcode,p.price,p.cost,p.stock,p.minStock]));case'export-product-movements':return featureCsv('product-movements',db.productMovements.map(m=>[m.date,db.products.find(p=>p.id===m.productId)?.name||'',m.type,m.quantity,m.amount,m.note]));case'attendance-import':return document.getElementById('featureAttendanceFile').click();case'attendance-export':return featureCsv('attendance',db.attendance.map(x=>[barberName(x.barberId),x.date,x.checkIn,x.checkOut,featureHours(x).toFixed(2),x.source,x.note]));case'clock-in':return featureClock(id,false);case'clock-out':return featureClock(id,true);case'payroll-adjust':return featurePayrollAdjustment();case'salary-base':return featureSetBaseSalary(id);case'salary-pay':return featurePaySalary(id);case'salary-slip':return featureSalarySlip(id);case'payroll-export':return featureCsv('payroll',db.payroll.map(x=>[barberName(x.barberId),x.period,x.baseSalary,x.commission,x.advance,x.incentive,x.deduction,x.paid,x.paymentDate,x.note]));case'offer-add':return featureOfferModal();case'offer-edit':return featureOfferModal(id);case'offer-toggle':{const o=db.offers.find(x=>x.id===id);o.active=!o.active;save();return render()}case'notifications-enable':return featureEnableNotifications();case'reminder-set':return featureReminderSet(id);case'reminder-wa':return featureReminderWhatsApp(id);case'appointment-add':return featureAppointmentModal();case'appointment-wait':return featureAppointmentModal('',true);case'appointment-edit':return featureAppointmentModal(id);case'appointment-delete':if(confirm('حذف الموعد؟')){db.appointments=db.appointments.filter(x=>x.id!==id);save();render()}return;case'appointment-session':{const a=db.appointments.find(x=>x.id===id);a.status='in_service';save();render();toast('بدأت الجلسة')}return;case'customer-history':return featureCustomerHistory(b.dataset.key);case'cart-clear':cart=[];featureActiveAppointmentId='';return render();case'checkout':return featureCheckout();case'invoice-print':return featurePrintInvoice(id);case'settings-save':db.settings.language=document.getElementById('featureLanguage').value;db.settings.theme=document.getElementById('featureTheme').value;db.settings.taxRate=Math.min(100,Math.max(0,Number(document.getElementById('featureTaxRate').value)||0));db.settings.loyaltyEarnRate=Math.max(1,Number(document.getElementById('featureLoyaltyRate').value)||10);db.settings.loyaltyPointValue=Math.max(0,Number(document.getElementById('featurePointValue').value)||0);save();render();return toast('تم حفظ الإعدادات');default:return}}
function featureCustomerHistory(key){const c=customerGroups().find(x=>x.key===key);if(!c)return;const points=featureCustomerPoints(c.phone);showModal('ملف '+esc(c.name),`<div class="modal-note">${esc(c.phone||'بدون هاتف')} · ${c.sales.length} زيارة · إنفاق ${money(salesTotal(c.sales))} · نقاط الولاء ${points}</div>${featureSalesRows(c.sales)}`,closeAction('إغلاق'))}
function featureCsv(name,rows){const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`halaq-${name}-${today}.csv`;a.click();URL.revokeObjectURL(a.href)}const featureBaseSettings=settingsPage;
function featureSettingsPage(){const html=featureBaseSettings(),marker='<div class="card panel" style="margin-top:15px"><div class="panel-header"><h2>إدارة البيانات</h2></div>';const panel=`<div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>اللغة والمظهر والضريبة والولاء</h2><p>إعدادات الفواتير والعملاء والواجهة</p></div></div><div class="form-grid"><div class="field"><label>لغة الواجهة</label><select class="select" id="featureLanguage"><option value="ar" ${db.settings.language==='ar'?'selected':''}>العربية</option><option value="en" ${db.settings.language==='en'?'selected':''}>English</option></select></div><div class="field"><label>المظهر</label><select class="select" id="featureTheme"><option value="light" ${db.settings.theme!=='dark'?'selected':''}>فاتح</option><option value="dark" ${db.settings.theme==='dark'?'selected':''}>داكن</option></select></div><div class="field"><label>ضريبة الفاتورة (%)</label><input class="input" id="featureTaxRate" type="number" min="0" max="100" step="0.01" value="${Number(db.settings.taxRate)||0}"></div><div class="field"><label>كل كم من العملة = نقطة ولاء</label><input class="input" id="featureLoyaltyRate" type="number" min="1" value="${Number(db.settings.loyaltyEarnRate)||10}"></div><div class="field"><label>قيمة النقطة عند الاستبدال</label><input class="input" id="featurePointValue" type="number" min="0" step="0.01" value="${Number(db.settings.loyaltyPointValue)||0.1}"></div></div><button class="btn btn-primary" data-fa="settings-save" style="margin-top:12px">حفظ إعدادات الإضافات</button><div class="hint" style="margin-top:10px">تسجيل الحضور متاح يدويًا واستيراد CSV. تكامل البصمة المباشر يعتمد على موديل الجهاز وبرنامجه. إشعار واتساب يحتاج إنترنت ويتم الإرسال يدويًا.</div></div>`;return html.replace(marker,panel+marker)}
