const featureArabic=Object.fromEntries(Object.entries(featureEnglish).map(([ar,en])=>[en,ar]));
function featureApplyLocale(root=document.body){const dict=db.settings.language==='en'?featureEnglish:featureArabic;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){const raw=n.nodeValue.trim();if(dict[raw])n.nodeValue=n.nodeValue.replace(raw,dict[raw])}root.querySelectorAll?.('[placeholder],[title]').forEach(el=>{for(const attr of ['placeholder','title'])if(el.hasAttribute(attr)&&dict[el.getAttribute(attr)])el.setAttribute(attr,dict[el.getAttribute(attr)])})}
function featureToggleLanguage(){db.settings.language=db.settings.language==='en'?'ar':'en';save();render()}
function featureToggleTheme(){db.settings.theme=db.settings.theme==='dark'?'light':'dark';save();featureApplyPrefs()}
document.getElementById('langToggle').onclick=featureToggleLanguage;
document.getElementById('themeToggle').onclick=featureToggleTheme;


/* Invoice lines with products are included in the same detailed report pipeline. */
const featureBaseReportData=buildReportData;
buildReportData=function(){
  const all=db.sales;
  const serviceSales=all.map(s=>({...s,items:(s.items||[]).filter(i=>!i.productId).map(i=>({...i}))})).filter(s=>s.items.length);
  db.sales=serviceSales;
  let data;
  try{data=featureBaseReportData()}finally{db.sales=all}
  const f=reportFilters,q=(f.query||'').trim().toLocaleLowerCase();
  if(!f.serviceId&&!f.consumableId){
    for(const sale of all){
      if(!sale.date||!reportDateInRange(sale.date)||(f.barberId&&sale.barberId!==f.barberId)||(f.payment&&sale.payment!==f.payment))continue;
      for(const item of (sale.items||[]).filter(i=>i.productId)){
        const product=db.products.find(p=>p.id===item.productId);if(!product)continue;
        if(q&&!`${sale.client} ${sale.clientPhone} ${product.name} ${barberName(sale.barberId)}`.toLocaleLowerCase().includes(q))continue;
        data.sales.push({sale,item:{...item},service:{name:`منتج: ${product.name}`},barber:barberName(sale.barberId),commission:0});
      }
    }
  }
  for(const row of data.sales){const sale=all.find(s=>s.id===row.sale.id)||row.sale;const base=Number(sale.subtotal)||((sale.items||[]).reduce((n,i)=>n+(Number(i.price)||0),0));const factor=base>0?(Number(sale.total)||0)/base:1;row.item.price=Math.round((Number(row.item.price)||0)*factor*100)/100}
  return data
};

