/* Per-cashier screen access. Existing accounts keep their original cashier defaults. */
const featurePermissionPages=['dashboard','cashier','appointments','customers','reminders','barbers','services','consumables','products','chairs','expenses','attendance','payroll','offers','reports'];
const featurePermissionLabels={dashboard:'الرئيسية',cashier:'الكاشير',appointments:'الحجوزات',customers:'العملاء',reminders:'التذكيرات',barbers:'الحلاقين',services:'الخدمات',consumables:'المستهلكات',products:'المنتجات والمخزون',chairs:'الكراسي',expenses:'المصروفات',attendance:'الحضور والانصراف',payroll:'الرواتب والعمولات',offers:'العروض والخصومات',reports:'التقارير',settings:'الإعدادات',users:'المستخدمين'};
/* A screen permission must not implicitly grant every manager action on that screen. */
const featureActionPermissions={
  'go-cashier':'cashier','clear-cart':'cashier','checkout':'cashier',
  'new-appointment':'appointments',
  'go-barbers':'barbers','add-barber':'barbers',
  'go-chairs':'chairs','add-chair':'chairs',
  'add-service':'services',
  'add-consumable':'consumables','purchase-consumable':'consumables',
  'add-expense':'expenses',
  'apply-report-filters':'reports','reset-report-filters':'reports','export-csv':'reports','print-report':'reports'
};
const featureBaseAction=action;
action=function(name){
  if(isManager())return featureBaseAction(name);
  const permittedPage=featureActionPermissions[name];
  if(!permittedPage||!featureCanAccess(permittedPage)){toast('الإجراء ده متاح للمدير فقط');return}
  if(!name.startsWith('go-')&&page!==permittedPage){toast('الإجراء غير متاح في هذه الصفحة');return}
  return featureBaseAction(name)
};
