showAuth=function(mode,error=''){
  const root=document.getElementById('authRoot'),heading=mode==='setup'?'إعداد حساب الأدمن':mode==='login'?'تسجيل الدخول':mode==='recovery'?'استعادة الدخول':'احتفظ برمز الاستعادة';let body='';
  if(mode==='show-recovery')body=`<p>احتفظ برمز استعادة حساب الأدمن خارج هذا الجهاز.</p><div class="field"><label>رمز الاستعادة</label><input id="recoveryShown" class="input" readonly value="${window.halaqRecovery||''}" /></div><button class="btn" id="downloadRecovery">تنزيل رمز الاستعادة</button><button class="btn btn-primary" id="finishRecovery">تم، افتح النظام</button>`;
  else if(mode==='setup')body=`<p>أنشئ كلمة مرور حساب <b>admin</b>. ستستخدمها لإدارة المستخدمين والصلاحيات.</p><div class="field"><label>كلمة المرور</label><input id="authPassword" class="input" type="password" autocomplete="new-password"  /></div><div class="field"><label>تأكيد كلمة المرور</label><input id="authConfirm" class="input" type="password" autocomplete="new-password"  /></div><button class="btn btn-primary" id="authSubmit">إنشاء حساب الأدمن</button>`;
  else if(mode==='login')body=`<p>أدخل اسم المستخدم وكلمة المرور.</p><div class="field"><label>اسم المستخدم</label><input id="authUsername" class="input" autocomplete="username" placeholder="اسم المستخدم" /></div><div class="field"><label>كلمة المرور</label><input id="authPassword" class="input" type="password" autocomplete="current-password" /></div><button class="btn btn-primary" id="authSubmit">دخول</button><button class="text-link" id="forgotPassword" style="margin-top:12px">استعادة حساب الأدمن</button>`;
  else body=`<p>أدخل رمز استعادة الأدمن وكلمة المرور الجديدة.</p><div class="field"><label>رمز الاستعادة</label><input id="recoveryInput" class="input" autocomplete="off" /></div><div class="field"><label>كلمة المرور الجديدة</label><input id="authPassword" class="input" type="password"  /></div><div class="field"><label>تأكيد كلمة المرور</label><input id="authConfirm" class="input" type="password"  /></div><button class="btn btn-primary" id="authSubmit">تعيين كلمة المرور</button>`;
  root.innerHTML=`<div class="auth-screen"><div class="auth-card"><div class="auth-brand">ح</div><h1>${heading}</h1>${body}<div class="auth-error" id="authError">${error}</div></div></div>`;
  const submit=document.getElementById('authSubmit');if(submit)submit.onclick=()=>submitAuth(mode);const forgot=document.getElementById('forgotPassword');if(forgot)forgot.onclick=()=>showAuth('recovery');const dl=document.getElementById('downloadRecovery');if(dl)dl.onclick=downloadRecoveryCode;
  const finish=document.getElementById('finishRecovery');if(finish)finish.onclick=()=>{root.innerHTML='';featureSetCurrentAdmin();unlockAfterAuth()};
};
submitAuth=async function(mode){const error=document.getElementById('authError'),pass=document.getElementById('authPassword')?.value||'';try{
  if(mode==='setup'){
    if(!pass)throw new Error('اكتب كلمة المرور');if(pass!==document.getElementById('authConfirm').value)throw new Error('كلمتا المرور غير متطابقتين');
    const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),hash=await passwordDigest(pass,salt),recovery=hexBytes(crypto.getRandomValues(new Uint8Array(12))).toUpperCase(),rsalt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),rhash=await passwordDigest(recovery,rsalt);
    localStorage.setItem(AUTH_KEY,JSON.stringify({salt,hash,recoverySalt:rsalt,recoveryHash:rhash}));featureSaveAdminProfile();window.halaqRecovery=recovery;showAuth('show-recovery');return
  }
  if(mode==='login'){
    const username=(document.getElementById('authUsername')?.value||'').trim().toLowerCase();
    if(username==='admin'){const auth=JSON.parse(localStorage.getItem(AUTH_KEY)||'null');if(!auth)throw new Error('حساب الأدمن يحتاج إعداد كلمة المرور أولًا');if(await passwordDigest(pass,auth.salt)!==auth.hash)throw new Error('اسم المستخدم أو كلمة المرور غير صحيحة');featureSetCurrentAdmin()}
    else{const user=appUsers.find(u=>u.active&&u.username.toLowerCase()===username);if(!user||await passwordDigest(pass,user.salt)!==user.hash)throw new Error('اسم المستخدم أو كلمة المرور غير صحيحة');setCurrentUser(user)}
    document.getElementById('authRoot').innerHTML='';unlockAfterAuth();return
  }
  const auth=JSON.parse(localStorage.getItem(AUTH_KEY)||'null'),recovery=document.getElementById('recoveryInput').value.trim().replace(/\s+/g,'').toUpperCase();if(!auth||await passwordDigest(recovery,auth.recoverySalt)!==auth.recoveryHash)throw new Error('رمز الاستعادة غير صحيح');
  if(!pass)throw new Error('اكتب كلمة المرور');if(pass!==document.getElementById('authConfirm').value)throw new Error('كلمتا المرور غير متطابقتين');
  const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),hash=await passwordDigest(pass,salt),rsalt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),newRecovery=hexBytes(crypto.getRandomValues(new Uint8Array(12))).toUpperCase(),rhash=await passwordDigest(newRecovery,rsalt);
  localStorage.setItem(AUTH_KEY,JSON.stringify({salt,hash,recoverySalt:rsalt,recoveryHash:rhash}));featureScheduleAccountSave();window.halaqRecovery=newRecovery;showAuth('show-recovery')
 }catch(e){if(error)error.textContent=e.message||'تعذر التحقق من كلمة المرور'}};

