  const roleSelect=document.getElementById('featureUserRole');if(roleSelect)roleSelect.onchange=()=>{const vals=roleSelect.value==='manager'?featurePermissionPages:['cashier','appointments','customers'];document.querySelectorAll('#featurePermissionChecks input[name="permissions"]').forEach(c=>c.checked=vals.includes(c.value))};
  document.getElementById('featureUserSave').onclick=async()=>{const f=new FormData(document.getElementById('featureUserForm')),name=String(f.get('name')||'').trim(),username=isAdminRow?'admin':String(f.get('username')||'').trim().toLowerCase(),newPass=String(f.get('password')||'');if(!name||!username)return toast('أدخل الاسم واسم المستخدم');if(!isAdminRow&&(!/^[a-z0-9._-]{3,32}$/.test(username)||appUsers.some(x=>x.username.toLowerCase()===username&&x.id!==id)))return toast('اسم المستخدم غير صالح أو مستخدم بالفعل');if(newPass&&newPass!==f.get('confirm'))return toast('كلمتا المرور غير متطابقتين');if(!editing&&!newPass)return toast('اكتب كلمة المرور');if(!editing&&newPass!==f.get('confirm'))return toast('كلمتا المرور غير متطابقتين');
    const chosen=f.getAll('permissions'),nextPerms=isAdminRow?[...new Set([...chosen,'dashboard','settings','users'])]:chosen,accountRole=isAdminRow?'admin':String(f.get('role')||'cashier');if(!isAdminRow&&!chosen.length)return toast('اختر شاشة واحدة على الأقل');
    if(isAdminRow){adminProfile={...adminProfile,name,username:'admin',role:'admin',permissions:nextPerms,active:true};featureSaveAdminProfile();if(newPass){const auth=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}'),salt=hexBytes(crypto.getRandomValues(new Uint8Array(16)));auth.salt=salt;auth.hash=await passwordDigest(newPass,salt);localStorage.setItem(AUTH_KEY,JSON.stringify(auth));featureScheduleAccountSave()}if(currentUser?.role==='admin')setCurrentUser(adminProfile)}
    else if(editing){const oldUsername=u.username;Object.assign(u,{name,username,role:accountRole,permissions:chosen});const oldId='u:'+oldUsername,newId='u:'+username;let detail=db.employeeDetails.find(x=>x.employeeId===oldId);if(detail){detail.employeeId=newId;detail.name=name}else{detail={employeeId:newId,baseSalary:0,name};db.employeeDetails.push(detail)}if(oldUsername!==username)for(const list of [db.attendance,db.payroll,db.payouts,db.sales])list.forEach(x=>{if(x.barberId===oldId)x.barberId=newId});if(newPass){const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16)));u.salt=salt;u.hash=await passwordDigest(newPass,salt)}saveUsers();save();if(currentUser?.id===u.id)setCurrentUser(u)}
    else{const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16))),hash=await passwordDigest(newPass,salt);appUsers.push({id:uid(),name,username,role:accountRole,permissions:chosen,salt,hash,active:true,createdAt:new Date().toISOString()});db.employeeDetails=db.employeeDetails||[];db.employeeDetails.push({employeeId:'u:'+username,baseSalary:0,name});saveUsers();save()}
    closeModal();render();toast('تم حفظ الحساب والصلاحيات')
  }
