const localDatabaseBridge=!!window.karbigiDesktop;
let accountSaveTimer=null,accountLoading=false;
const originalSaveUsers=saveUsers;
saveUsers=function(){originalSaveUsers();featureScheduleAccountSave()};
function featureScheduleAccountSave(){
  if(!localDatabaseBridge||accountLoading||!localStorage.getItem(AUTH_KEY))return;
  const updatedAt=Date.now();localStorage.setItem(KEY+'_accounts_saved_at',String(updatedAt));
  clearTimeout(accountSaveTimer);
  accountSaveTimer=setTimeout(async()=>{
    const payload={updatedAt,auth:JSON.parse(localStorage.getItem(AUTH_KEY)),users:appUsers,adminProfile};
    try{await window.karbigiDesktop.writeAccounts(payload)}
    catch(error){console.error(error);toast('تعذر حفظ حسابات المستخدمين داخل المشروع')}
  },500);
}
async function featureLoadProjectAccounts(){
  if(!localDatabaseBridge)return;
  const saved=await window.karbigiDesktop.readAccounts();
  if(!saved)return;
  if(!saved.auth?.salt||!saved.auth?.hash)return;
  const localTime=Number(localStorage.getItem(KEY+'_accounts_saved_at'))||0;
  if(localStorage.getItem(AUTH_KEY)&&localTime>Number(saved.updatedAt||0)){featureScheduleAccountSave();return}
  accountLoading=true;
  try{
    localStorage.setItem(AUTH_KEY,JSON.stringify(saved.auth));
    appUsers=(Array.isArray(saved.users)?saved.users:[]).filter(u=>u&&u.username!=='admin').map(u=>({...u,role:u.role==='manager'?'manager':'cashier',active:u.active!==false,permissions:Array.isArray(u.permissions)?u.permissions:['cashier','appointments','customers']}));
    localStorage.setItem(USERS_KEY,JSON.stringify(appUsers));
    if(saved.adminProfile){adminProfile={...adminProfile,...saved.adminProfile,username:'admin',role:'admin',permissions:[...new Set([...(saved.adminProfile.permissions||[]),'dashboard','settings','users'])]};localStorage.setItem(ADMIN_PROFILE_KEY,JSON.stringify(adminProfile))}
    localStorage.setItem(KEY+'_accounts_saved_at',String(saved.updatedAt||Date.now()));
  }finally{accountLoading=false}
}
async function bridgeDatabase(method,bytes){
  if(method==='GET')return window.karbigiDesktop.readDatabase();
  await window.karbigiDesktop.writeDatabase(bytes);
  return null;
}
if(localDatabaseBridge){
  writeDatabaseWorkbook=async function(){
    if(!excelSyncing)return;
    const snapshot=JSON.stringify(db),savedAt=dbSavedAt;
    await bridgeDatabase('POST',serializeDatabaseWorkbook(savedAt));
    if(JSON.stringify(db)!==snapshot)scheduleExcelSave();
    else setExcelStatus('connected','Excel محفوظ تلقائيًا');
  };
  restoreExcelHandle=async function(){
    setExcelStatus('saving','جاري فتح Database.xlsx…');
    try{
      const bytes=await bridgeDatabase('GET');
      const parsed=workbookData(XLSX.read(bytes,{type:'array'}));
      excelHandle={automatic:true};excelSyncing=true;
      if(parsed.savedAt>dbSavedAt){
        db=parsed.data;dbSavedAt=parsed.savedAt;
        localStorage.setItem(KEY,JSON.stringify(db));
        localStorage.setItem(SAVE_TIME_KEY,String(dbSavedAt));
      }else if(!dbSavedAt&&!legacyLocalData){db=parsed.data;persistLocal();await writeDatabaseWorkbook()}
      else if(dbSavedAt>parsed.savedAt){await writeDatabaseWorkbook()}
      setExcelStatus('connected','Excel محفوظ تلقائيًا');render();
    }catch(error){
      console.error(error);excelSyncing=false;excelHandle=null;
      setExcelStatus('','تعذر الحفظ التلقائي في Excel');
      toast('تعذر فتح Database.xlsx؛ البيانات المحلية ما زالت محفوظة');
    }
  };
  connectExcel=restoreExcelHandle;
  excelNotice=()=>'';
  document.getElementById('excelIndicator').title='حفظ تلقائي في Database/Database.xlsx';
  const originalSettingsPage=featurePageMap.settings;
  featurePageMap.settings=function(){return originalSettingsPage()
    .replace('اربط الملف الموجود داخل مجلد Database أول مرة. اترك الملف مغلقًا في Excel أثناء تشغيل التطبيق حتى يقدر يحفظ التعديلات.','الملف مربوط تلقائيًا من مجلد Database داخل المشروع. اتركه مغلقًا في Excel أثناء تشغيل التطبيق.')
    .replace(/<button class="btn btn-primary" data-action="connect-excel">[^<]*<\/button>/,'')
    .replace('النسخ اليومية تُحفظ داخل مجلد Backups بجوار مجلد Database. اختر مجلد المشروع مرة واحدة لتفعيلها.','تُحفظ نسخة يومية تلقائيًا في مجلد Backups بجوار قاعدة البيانات.')
    .replace('لم يتم اختيار مجلد النسخ اليومي','النسخ اليومي مفعّل تلقائيًا')
    .replace(/<button class="btn btn-primary" data-action="backup-folder">[^<]*<\/button>/,'');};
  chooseBackupFolder=()=>toast('النسخ اليومية مفعّلة تلقائيًا داخل Backups');
  createDailyBackup=async function(){
    try{
      await window.karbigiDesktop.backupDatabase(iso());
      const status=document.getElementById('backupStatusText');
      if(status){status.textContent=`آخر نسخة: ${dateFmt(iso())}`;status.className='backup-status ok'}
    }catch(error){console.error(error);toast('تعذر إنشاء النسخة اليومية')}
  };
  restoreBackupDirectory=async()=>{await createDailyBackup()};
  restoreExcelBackup=async function(){
    try{
      const bytes=await window.karbigiDesktop.selectBackup();
      if(!bytes||!confirm('استعادة هذه النسخة واستبدال البيانات الحالية؟'))return;
      const parsed=workbookData(XLSX.read(bytes,{type:'array'}));
      db=parsed.data;persistLocal();await writeDatabaseWorkbook();render();toast('تمت استعادة النسخة الاحتياطية');
    }catch(error){console.error(error);toast('ملف النسخة غير صالح أو تعذر قراءته')}
  };
}
const featureBaseReportsPage=reportsPage;
reportsPage=function(){
  const within=date=>date&&(!reportFilters.from||date>=reportFilters.from)&&(!reportFilters.to||date<=reportFilters.to);
  const sales=db.sales.filter(s=>within(s.date)),expenses=db.expenses.filter(e=>within(e.date)),payouts=db.payouts.filter(p=>within(p.date));
  const income=salesTotal(sales),cost=expenseTotal(expenses),fees=sales.reduce((n,s)=>n+commissionFor(s),0);
  const cashIn=salesTotal(sales.filter(s=>s.payment==='cash'));
  const cashOut=expenseTotal(expenses.filter(e=>e.payment==='cash'))+expenseTotal(payouts.filter(p=>p.payment==='cash'));
  return featureBaseReportsPage()+`<div class="card panel" style="margin-top:15px"><div class="panel-header"><div><h2>ملخص حسابات المحل</h2><p>كل عمليات المحل ضمن فترة التاريخ المختارة، بغض النظر عن فلاتر الحلاق والخدمة والبحث.</p></div></div><div class="grid stats-grid">${stat('إجمالي المبيعات',money(income),'↗',sales.length+' فاتورة خدمات ومنتجات')}${stat('مصروفات المحل',money(cost),'↙',expenses.length+' مصروف مسجل')}${stat('عمولات مستحقة',money(fees),'✂','على الخدمات بعد الخصومات')}${stat('الرصيد قبل الرواتب الأساسية',money(income-cost-fees),'◈','مبيعات − مصروفات − عمولات')}</div><div class="kpi-strip" style="flex-wrap:wrap"><span>نقد داخل <b>${money(cashIn)}</b></span><span>نقد خارج <b>${money(cashOut)}</b></span><span>صافي حركة النقد <b>${money(cashIn-cashOut)}</b></span><span>مدفوعات الفريق <b>${money(expenseTotal(payouts))}</b></span></div></div>`;
};
const featureBrandRender=render;
render=function(){
  if(db.settings.shop==='صالون الحلاقة'){db.settings.shop='كربيجي';save()}
  const shopName=String(db.settings.shop||'كربيجي');
  document.getElementById('shopNameSide').textContent=shopName;
  document.getElementById('shopNameTop').textContent=shopName;
  return featureBrandRender();
};
async function featureStartWithAdminPassword(){
  if(localStorage.getItem(AUTH_KEY)){lockApp();return}
  const salt=hexBytes(crypto.getRandomValues(new Uint8Array(16)));
  const recovery=hexBytes(crypto.getRandomValues(new Uint8Array(12))).toUpperCase();
  const recoverySalt=hexBytes(crypto.getRandomValues(new Uint8Array(16)));
  const [hash,recoveryHash]=await Promise.all([
    passwordDigest('123456789',salt),
    passwordDigest(recovery,recoverySalt)
  ]);
  localStorage.setItem(AUTH_KEY,JSON.stringify({salt,hash,recoverySalt,recoveryHash}));
  featureSaveAdminProfile();
  window.halaqRecovery=recovery;
  showAuth('show-recovery');
}
(async()=>{await featureLoadProjectAccounts();await featureStartWithAdminPassword();featureScheduleAccountSave()})().catch(error=>{console.error(error);lockApp()});
